import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCreateFormMutation, QuestionType } from '../generated/graphql';
import { Plus, Trash, Save } from 'lucide-react';

interface QuestionDraft {
  type: QuestionType;
  title: string;
  required: boolean;
  options: string[];
}

const FormBuilderPage: React.FC = () => {
  const navigate = useNavigate();
  const [createForm, { isLoading }] = useCreateFormMutation();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [questions, setQuestions] = useState<QuestionDraft[]>([]);

  const addQuestion = () => {
    setQuestions([...questions, { type: QuestionType.Text, title: '', required: false, options: [''] }]);
  };

  const updateQuestion = (index: number, updates: Partial<QuestionDraft>) => {
    const newQuestions = [...questions];
    newQuestions[index] = { ...newQuestions[index]!, ...updates };
    setQuestions(newQuestions);
  };

  const removeQuestion = (index: number) => {
    setQuestions(questions.filter((_, i) => i !== index));
  };

  const addOption = (qIndex: number) => {
    const q = questions[qIndex]!;
    updateQuestion(qIndex, { options: [...q.options, ''] });
  };

  const updateOption = (qIndex: number, oIndex: number, val: string) => {
    const q = questions[qIndex]!;
    const newOptions = [...q.options];
    newOptions[oIndex] = val;
    updateQuestion(qIndex, { options: newOptions });
  };

  const handleSave = async () => {
    try {
      await createForm({
        title,
        description,
        questions: questions.map(q => ({
          type: q.type,
          title: q.title,
          required: q.required,
          options: (q.type === QuestionType.MultipleChoice || q.type === QuestionType.Checkbox) ? q.options : []
        }))
      }).unwrap();
      navigate('/');
    } catch (err) {
      alert('Failed to save form');
    }
  };

  return (
    <div className="max-w-3xl mx-auto p-8 bg-gray-50 min-h-screen">
      <h1 className="text-3xl font-bold mb-8 text-center">Create New Form</h1>

      <div className="bg-white p-6 rounded-lg shadow-md border-t-8 border-purple-700 mb-6">
        <input
          type="text"
          placeholder="Form Title"
          className="text-4xl font-bold w-full border-b focus:border-purple-700 outline-none mb-4 p-2"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <textarea
          placeholder="Form Description"
          className="w-full border-b focus:border-purple-700 outline-none p-2 resize-none"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>

      {questions.map((q, qIndex) => (
        <div key={qIndex} className="bg-white p-6 rounded-lg shadow-md mb-6 border-l-4 border-blue-500">
          <div className="flex gap-4 mb-4">
            <input
              type="text"
              placeholder="Question Title"
              className="flex-1 text-xl font-semibold border-b outline-none p-2"
              value={q.title}
              onChange={(e) => updateQuestion(qIndex, { title: e.target.value })}
            />
            <select
              className="border p-2 rounded"
              value={q.type}
              onChange={(e) => updateQuestion(qIndex, { type: e.target.value as QuestionType })}
            >
              <option value={QuestionType.Text}>Text</option>
              <option value={QuestionType.MultipleChoice}>Multiple Choice</option>
              <option value={QuestionType.Checkbox}>Checkbox</option>
              <option value={QuestionType.Date}>Date</option>
            </select>
          </div>

          {(q.type === QuestionType.MultipleChoice || q.type === QuestionType.Checkbox) && (
            <div className="ml-4 space-y-2 mb-4">
              {q.options.map((opt, oIndex) => (
                <div key={oIndex} className="flex items-center gap-2">
                  <div className={q.type === QuestionType.MultipleChoice ? "w-4 h-4 rounded-full border" : "w-4 h-4 border"} />
                  <input
                    type="text"
                    placeholder={`Option ${oIndex + 1}`}
                    className="border-b outline-none p-1 flex-1"
                    value={opt}
                    onChange={(e) => updateOption(qIndex, oIndex, e.target.value)}
                  />
                  <button onClick={() => updateQuestion(qIndex, { options: q.options.filter((_, i) => i !== oIndex) })}>
                    <Trash className="w-4 h-4 text-gray-400 hover:text-red-500" />
                  </button>
                </div>
              ))}
              <button
                onClick={() => addOption(qIndex)}
                className="text-blue-600 text-sm hover:underline flex items-center gap-1"
              >
                <Plus className="w-4 h-4" /> Add Option
              </button>
            </div>
          )}

          <div className="flex justify-end gap-4 border-t pt-4">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={q.required}
                onChange={(e) => updateQuestion(qIndex, { required: e.target.checked })}
              />
              <span className="text-sm text-gray-600">Required</span>
            </label>
            <button onClick={() => removeQuestion(qIndex)}>
              <Trash className="w-5 h-5 text-gray-500 hover:text-red-500" />
            </button>
          </div>
        </div>
      ))}

      <div className="flex justify-between items-center mt-8">
        <button
          onClick={addQuestion}
          className="flex items-center gap-2 bg-blue-100 text-blue-700 px-4 py-2 rounded hover:bg-blue-200"
        >
          <Plus className="w-5 h-5" /> Add Question
        </button>
        <button
          onClick={handleSave}
          disabled={isLoading || !title}
          className="flex items-center gap-2 bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700 disabled:bg-gray-400"
        >
          <Save className="w-5 h-5" /> {isLoading ? 'Saving...' : 'Save Form'}
        </button>
      </div>
    </div>
  );
};

export default FormBuilderPage;
